import { escapeHtml } from '#lib/mailer'

export interface EmailLayoutInput {
	title: string
	intro: string
	body: string
	action?: { label: string; url: string }
}

/**
 * Minimal HTML shell for feature emails. Inline styles only: no external CSS,
 * no class names, so it renders the same in every client. Plain text is
 * generated by the template, not here.
 */
export function emailLayout({ title, intro, body, action }: EmailLayoutInput): string {
	const safeTitle = escapeHtml(title)
	const safeIntro = escapeHtml(intro)
	const button = action
		? `<p style="margin:24px 0"><a href="${escapeHtml(action.url)}" style="background:#111827;color:#ffffff;padding:12px 20px;border-radius:6px;text-decoration:none;display:inline-block">${escapeHtml(action.label)}</a></p>`
		: ''

	return `<!doctype html>
<html>
	<body style="margin:0;padding:24px;background:#f8fafc;font-family:system-ui,-apple-system,'Segoe UI',sans-serif;color:#0f172a">
		<div style="max-width:560px;margin:0 auto;background:#ffffff;border:1px solid #e2e8f0;border-radius:8px;padding:24px">
			<h1 style="margin:0 0 8px;font-size:20px">${safeTitle}</h1>
			<p style="margin:0 0 16px;color:#475569">${safeIntro}</p>
			${body}
			${button}
			<p style="margin:24px 0 0;font-size:12px;color:#94a3b8">Sent by the Elysia Boilerplate API.</p>
		</div>
	</body>
</html>`
}
